WITH manifest AS (SELECT $1::jsonb m),
concept_ids AS (SELECT jsonb_array_elements_text(m->'concepts') id FROM manifest),
observation_ids AS (SELECT jsonb_array_elements_text(m->'observations') id FROM manifest),
path_ids AS (SELECT jsonb_array_elements_text(m->'paths') id FROM manifest),
evidence_ids AS (SELECT jsonb_array_elements_text(m->'evidenceLinks') id FROM manifest),
public_series AS (SELECT DISTINCT o.series_key FROM atlas_evidence.observations o JOIN observation_ids p ON p.id=o.observation_id WHERE o.publication_hold IS FALSE AND o.source_is_published IS TRUE),
themes AS (SELECT * FROM atlas_reasoning.thematic_groups WHERE review_status<>'rejected' AND taxonomy_namespace='editorial_synthesis_12_v1'),
cases AS (SELECT * FROM atlas_reasoning.decision_cases WHERE review_status<>'rejected'),
frameworks AS (SELECT * FROM atlas_reasoning.service_frameworks WHERE review_status<>'rejected'),
stages AS (SELECT s.* FROM atlas_reasoning.service_stages s JOIN frameworks USING(framework_id)),
refs AS (SELECT r.* FROM atlas_reasoning.case_reference_cards r JOIN cases USING(case_id) JOIN atlas_reasoning.sources s USING(source_id) WHERE r.review_status<>'rejected' AND r.url ~ '^https?://' AND s.url ~ '^https?://'),
metrics AS (SELECT m.* FROM atlas_reasoning.framework_metrics m JOIN frameworks USING(framework_id) WHERE m.review_status<>'rejected'),
case_metrics AS (SELECT m.* FROM atlas_reasoning.case_metric_candidates m JOIN cases USING(case_id) WHERE m.review_status<>'rejected'),
series_meta AS (SELECT s.* FROM atlas_evidence.series_metadata s JOIN public_series USING(series_key)),
comparisons AS (SELECT c.* FROM atlas_reasoning.comparison_groups c WHERE c.review_status<>'rejected' AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements_text(c.series_keys) k WHERE NOT EXISTS(SELECT 1 FROM public_series p WHERE p.series_key=k.value)))
SELECT jsonb_build_object(
'exclusions',jsonb_build_object('caseRoutesNotPublishable',(SELECT count(*) FROM atlas_reasoning.case_routes r JOIN cases USING(case_id) WHERE NOT EXISTS(SELECT 1 FROM path_ids p WHERE p.id=r.path_id)),'serviceTransitionsNotPublishable',(SELECT count(*) FROM atlas_reasoning.service_transitions t WHERE t.review_status='rejected' OR NOT EXISTS(SELECT 1 FROM stages s WHERE s.stage_id=t.from_stage_id) OR NOT EXISTS(SELECT 1 FROM stages s WHERE s.stage_id=t.to_stage_id))),
'modelVersion',1,'generatedAt',now(),'policy','Toimituksellinen aineisto. Palvelusiirtymä, teemajäsenyys, lähdeviite ja kausaalinen mekanismi ovat eri suhteita. Tarkistusta odottavat kirjaukset ovat ehdotuksia.',
 'themes',coalesce((SELECT jsonb_agg(jsonb_build_object('id',theme_id,'label',label_fi,'description',description,'namespace',taxonomy_namespace,'reviewStatus',review_status) ORDER BY theme_id) FROM themes),'[]'::jsonb),
 'memberships',coalesce((SELECT jsonb_agg(jsonb_build_object('conceptId',c.concept_id,'themeId',c.theme_id,'rationale',c.rationale,'reviewStatus',c.review_status) ORDER BY c.theme_id,c.concept_id) FROM atlas_reasoning.concept_themes c JOIN themes USING(theme_id) JOIN concept_ids i ON i.id=c.concept_id WHERE c.review_status<>'rejected'),'[]'::jsonb),
 'suppressedConceptIds',coalesce((SELECT jsonb_agg(DISTINCT c.concept_id) FROM atlas_reasoning.concept_themes c JOIN themes USING(theme_id) JOIN concept_ids i ON i.id=c.concept_id WHERE NOT EXISTS(SELECT 1 FROM atlas_reasoning.concept_themes x JOIN themes t USING(theme_id) WHERE x.concept_id=c.concept_id AND x.review_status<>'rejected')),'[]'::jsonb),
 'cases',coalesce((SELECT jsonb_agg(jsonb_build_object('case_id',case_id,'title',title,'case_kind',case_kind,'decision_or_practice',decision_or_practice,'goal',goal,'decision_actors',decision_actors,'influence_conditions',influence_conditions,'beneficiaries',beneficiaries,'cost_bearers',cost_bearers,'time_horizon',time_horizon,'repair_responsibility',repair_responsibility,'evidence_summary',evidence_summary,'alternative_explanation',alternative_explanation,'limitations',limitations,'review_status',review_status) ORDER BY case_id) FROM cases),'[]'::jsonb),
 'caseRoutes',coalesce((SELECT jsonb_agg(jsonb_build_object('case_id',r.case_id,'path_id',r.path_id,'route_kind',r.route_kind,'branch_conditions',r.branch_conditions) ORDER BY r.case_id,r.path_id) FROM atlas_reasoning.case_routes r JOIN cases USING(case_id) JOIN path_ids p ON p.id=r.path_id),'[]'::jsonb),
 'caseReferences',coalesce((SELECT jsonb_agg(jsonb_build_object('reference_id',reference_id,'case_id',case_id,'source_id',source_id,'title',title,'url',url,'reference_kind',reference_kind,'locator',locator,'relation_type',relation_type,'scope_note',scope_note,'verification',verification,'review_status',review_status) ORDER BY reference_id) FROM refs),'[]'::jsonb),
 'sources',coalesce((SELECT jsonb_agg(jsonb_build_object('source_id',s.source_id,'title',s.title,'url',s.url,'source_kind',s.source_kind,'source_version',s.source_version,'publication_year',s.publication_year,'verification',s.verification,'checked_on',s.checked_on) ORDER BY s.source_id) FROM atlas_reasoning.sources s WHERE EXISTS(SELECT 1 FROM refs r WHERE r.source_id=s.source_id) OR EXISTS(SELECT 1 FROM atlas_reasoning.case_stage_roles r JOIN cases USING(case_id) WHERE r.source_id=s.source_id AND r.review_status<>'rejected')),'[]'::jsonb),
 'frameworks',coalesce((SELECT jsonb_agg(jsonb_build_object('framework_id',framework_id,'title',title,'principle',principle,'scope_note',scope_note,'review_status',review_status) ORDER BY framework_id) FROM frameworks),'[]'::jsonb),
 'stages',coalesce((SELECT jsonb_agg(jsonb_build_object('stage_id',stage_id,'framework_id',framework_id,'label_fi',label_fi,'definition',definition,'sort_order',sort_order) ORDER BY sort_order) FROM stages),'[]'::jsonb),
 'transitions',coalesce((SELECT jsonb_agg(jsonb_build_object('transition_id',t.transition_id,'from_stage_id',t.from_stage_id,'to_stage_id',t.to_stage_id,'transition_kind',t.transition_kind,'condition_text',t.condition_text,'observability_note',t.observability_note,'review_status',t.review_status) ORDER BY t.transition_id) FROM atlas_reasoning.service_transitions t JOIN stages a ON a.stage_id=t.from_stage_id JOIN stages b ON b.stage_id=t.to_stage_id WHERE t.review_status<>'rejected'),'[]'::jsonb),
 'caseEvidence',coalesce((SELECT jsonb_agg(jsonb_build_object('case_id',r.case_id,'stage_id',r.stage_id,'observation_id',r.observation_id,'evidence_role',r.evidence_role,'metric_id',r.metric_id,'rationale',r.rationale,'limitations',r.limitations,'review_status',r.review_status) ORDER BY r.case_id,r.stage_id,r.observation_id) FROM atlas_reasoning.case_stage_evidence r JOIN cases USING(case_id) JOIN stages USING(stage_id) JOIN observation_ids o ON o.id=r.observation_id WHERE r.review_status<>'rejected'),'[]'::jsonb),
 'caseRoles',coalesce((SELECT jsonb_agg(jsonb_build_object('case_id',r.case_id,'stage_id',r.stage_id,'actor_id',r.actor_id,'actor_label',a.label_fi,'role_kind',r.role_kind,'responsibility_scope',r.responsibility_scope,'information_access',r.information_access,'authority_scope',r.authority_scope,'resource_conditions',r.resource_conditions,'formal_duty_status',r.formal_duty_status,'legal_basis',r.legal_basis,'source_id',r.source_id,'validity_start',r.validity_start,'validity_end',r.validity_end,'limitations',r.limitations,'review_status',r.review_status) ORDER BY r.case_id,r.stage_id,r.actor_id) FROM atlas_reasoning.case_stage_roles r JOIN cases USING(case_id) JOIN stages USING(stage_id) JOIN atlas_reasoning.actor_types a USING(actor_id) WHERE r.review_status<>'rejected'),'[]'::jsonb),
 'frameworkCaseLinks',coalesce((SELECT jsonb_agg(jsonb_build_object('framework_id',r.framework_id,'case_id',r.case_id,'applicability',r.applicability,'limitations',r.limitations,'review_status',r.review_status)) FROM atlas_reasoning.framework_case_links r JOIN cases USING(case_id) JOIN frameworks USING(framework_id) WHERE r.review_status<>'rejected'),'[]'::jsonb),
 'frameworkThemeLinks',coalesce((SELECT jsonb_agg(jsonb_build_object('framework_id',r.framework_id,'theme_id',r.theme_id,'rationale',r.rationale)) FROM atlas_reasoning.framework_theme_links r JOIN themes USING(theme_id) JOIN frameworks USING(framework_id)),'[]'::jsonb),
 'metrics',coalesce((SELECT jsonb_agg(jsonb_build_object('metric_id',metric_id,'framework_id',framework_id,'label_fi',label_fi,'operational_definition',operational_definition,'numerator',numerator,'denominator',denominator,'unit',unit,'clock_start',clock_start,'clock_end',clock_end,'non_user_coverage',non_user_coverage,'missing_data_rule',missing_data_rule,'limitations',limitations,'data_status',data_status,'review_status',review_status)) FROM metrics),'[]'::jsonb),
 'caseMetrics',coalesce((SELECT jsonb_agg(jsonb_build_object('metric_id',metric_id,'case_id',case_id,'concept_id',concept_id,'label_fi',label_fi,'operational_definition',operational_definition,'unit',unit,'denominator',denominator,'required_breakdowns',required_breakdowns,'collection_plan',collection_plan,'limitations',limitations,'data_status',data_status,'review_status',review_status)) FROM case_metrics),'[]'::jsonb),
 'metricStageLinks',coalesce((SELECT jsonb_agg(jsonb_build_object('metric_id',r.metric_id,'stage_id',r.stage_id,'rationale',r.rationale)) FROM atlas_reasoning.metric_stage_links r JOIN metrics USING(metric_id) JOIN stages USING(stage_id)),'[]'::jsonb),
 'metricCaseLinks',coalesce((SELECT jsonb_agg(jsonb_build_object('case_id',r.case_id,'metric_id',r.metric_id,'case_metric_id',r.case_metric_id,'rationale',r.rationale,'review_status',r.review_status)) FROM atlas_reasoning.metric_case_links r JOIN cases USING(case_id) WHERE r.review_status<>'rejected' AND EXISTS(SELECT 1 FROM metrics m WHERE m.metric_id=r.metric_id) AND EXISTS(SELECT 1 FROM case_metrics m WHERE m.metric_id=r.case_metric_id)),'[]'::jsonb),
 'seriesMetadata',coalesce((SELECT jsonb_agg(jsonb_build_object('series_key',series_key,'definition',definition,'population',population,'frequency',frequency,'unit',unit,'price_basis',price_basis,'value_kind',value_kind,'coverage_start',coverage_start,'coverage_end',coverage_end,'missing_years',missing_years,'method_breaks',method_breaks,'comparability',comparability,'source_version',source_version,'metadata_status',metadata_status) ORDER BY series_key) FROM series_meta),'[]'::jsonb),
 'dimensions',coalesce((SELECT jsonb_agg(jsonb_build_object('dimension_id',dimension_id,'label_fi',label_fi,'definition',definition,'privacy_note',privacy_note)) FROM atlas_evidence.stratification_dimensions),'[]'::jsonb),
 'seriesDimensions',coalesce((SELECT jsonb_agg(jsonb_build_object('series_key',d.series_key,'dimension_id',d.dimension_id,'availability',d.availability,'source_field',d.source_field,'category_value',d.category_value,'category_label',d.category_label,'comparability',d.comparability,'review_status',d.review_status) ORDER BY d.series_key,d.dimension_id) FROM atlas_evidence.series_dimensions d JOIN series_meta USING(series_key) WHERE d.review_status<>'rejected'),'[]'::jsonb),
 'seriesThemes',coalesce((SELECT jsonb_agg(jsonb_build_object('series_key',r.series_key,'theme_id',r.theme_id,'rationale',r.rationale,'review_status',r.review_status)) FROM atlas_reasoning.series_themes r JOIN themes USING(theme_id) JOIN public_series USING(series_key) WHERE r.review_status<>'rejected'),'[]'::jsonb),
 'comparisons',coalesce((SELECT jsonb_agg(jsonb_build_object('comparison_id',comparison_id,'title',title,'indicator_definition',indicator_definition,'included_geographies',included_geographies,'desired_geographies',desired_geographies,'comparability',comparability,'limitations',limitations,'series_keys',series_keys,'review_status',review_status)) FROM comparisons),'[]'::jsonb),
 'comparisonRows',coalesce((SELECT jsonb_agg(jsonb_build_object('row_id',r.run_id||':'||r.row_id,'source_row_id',r.row_id,'run_id',r.run_id,'title',r.title,'population_and_time',r.population_and_time,'outcomes',r.outcomes,'evidence_link_ids',r.evidence_link_ids,'limitations',r.limitations,'review_status',r.review_status)) FROM atlas_reasoning.evidence_comparison_rows r WHERE r.review_status<>'rejected' AND jsonb_array_length(r.evidence_link_ids)>0 AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements_text(r.evidence_link_ids) x WHERE NOT EXISTS(SELECT 1 FROM evidence_ids e WHERE e.id=x.value))),'[]'::jsonb),
 'evidenceGaps',coalesce((SELECT jsonb_agg(jsonb_build_object('gap_id',g.gap_id,'theme_id',g.theme_id,'title',g.title,'required_evidence',g.required_evidence,'candidate_sources',g.candidate_sources,'status',g.status,'related_conclusions',g.related_conclusions,'limitations',g.limitations) ORDER BY g.gap_id) FROM atlas_reasoning.evidence_gaps g JOIN themes USING(theme_id) WHERE g.status<>'rejected'),'[]'::jsonb)
) publication;
